package com.bank.records;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

// One line declares an immutable data carrier. The compiler generates:
//  - private final fields: from, to, amount, tags
//  - canonical constructor
//  - accessors: from(), to(), amount(), tags()
//  - equals()/hashCode() over all components, and toString()
public record TransferReceipt(String from, String to, BigDecimal amount, List<String> tags) {

    // COMPACT CONSTRUCTOR: runs BEFORE fields are assigned → validate + normalize.
    public TransferReceipt {
        if (from == null || from.isBlank()) throw new IllegalArgumentException("from required");
        if (to == null || to.isBlank())     throw new IllegalArgumentException("to required");
        if (amount == null || amount.signum() <= 0)
            throw new IllegalArgumentException("amount must be positive");
        amount = amount.setScale(2, RoundingMode.HALF_UP);   // normalize money
        tags = List.copyOf(tags);     // DEFENSIVE COPY: a mutable List component is unsafe otherwise
    }

    // You can add extra methods and override generated ones (mask the accounts in logs).
    @Override
    public String toString() {
        return "TransferReceipt[from=" + mask(from) + ", to=" + mask(to) + ", amount=" + amount + "]";
    }
    private static String mask(String acc) {
        return acc.length() <= 3 ? acc : "***" + acc.substring(acc.length() - 3);
    }

    // A static factory is allowed (records can have static members).
    public static TransferReceipt of(String from, String to, BigDecimal amount) {
        return new TransferReceipt(from, to, amount, List.of());
    }
}

// A record cannot extend a class (it implicitly extends java.lang.Record) and is final:
//   record Premium(...) extends TransferReceipt { }  // ← DOES NOT COMPILE
// but it CAN implement interfaces:
//   record TransferReceipt(...) implements Comparable<TransferReceipt> { }  // allowed
