package com.bank.records;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class RecordDemo {
    private static final Logger log = Logger.getLogger(RecordDemo.class.getName());

    public static void main(String[] args) {
        // Create a receipt for Rajesh → Priya; amount normalized to 2 decimals.
        TransferReceipt r1 = new TransferReceipt("SAV2001", "CUR3001",
            new BigDecimal("50000.5"), List.of("UPI", "INSTANT"));
        log.info(() -> "receipt=" + r1);                       // uses overridden toString
        log.info(() -> "amount via accessor = Rs." + r1.amount());   // generated accessor

        // Value-based equals: two receipts with equal components are equal.
        TransferReceipt r2 = new TransferReceipt("SAV2001", "CUR3001",
            new BigDecimal("50000.50"), List.of("UPI", "INSTANT"));
        log.info(() -> "r1.equals(r2) = " + r1.equals(r2));    // true (generated equals)

        // Defensive copy proven: mutating the source list does NOT affect the record.
        List<String> src = new ArrayList<>(List.of("ACH"));
        TransferReceipt r3 = new TransferReceipt("SAV2001", "CUR3001",
            new BigDecimal("1000"), src);
        src.add("MUTATED");
        log.info(() -> "record tags unaffected by source mutation = " + r3.tags());

        // Compact constructor validation rejects bad input.
        try {
            TransferReceipt.of("SAV2001", "CUR3001", new BigDecimal("-1"));
        } catch (IllegalArgumentException e) {
            log.warning(() -> "validation rejected: " + e.getMessage());
        }
    }
}
